// The generated half of the IPC contract: `commands` is the call surface, and
// `eventTopics` is the manifest the event bus publishes on. Both are regenerated by
// `cargo xtask gen-ipc`, so neither is edited by hand.
export { commands, eventTopics } from "./generated/bindings.js";
export type {
  AppError,
  BuildInfo,
  ErrorCode,
  EventHealth,
  EventTopicName,
  Health,
  JobRecord,
  JobStarted,
  JobState,
  SchedulerHealth,
} from "./generated/bindings.js";

export { getBuildInfo, isSuccessful, unwrap } from "./client.js";
export type { CommandResult } from "./client.js";
export {
  describeIpcError,
  GENERIC_MESSAGE,
  IPC_ERROR_CODES,
  IPC_ERROR_COPY,
  isIpcErrorCode,
  normalizeIpcError,
} from "./errors.js";
export type { IpcError, IpcErrorCopy, IpcErrorMessageKey } from "./errors.js";
